<template>
  <nav class="space-y-1">
    <template v-for="group in items" :key="group.label">
      <p v-if="group.label" class="sidebar-section">{{ group.label }}</p>
      <template v-for="item in group.items" :key="item.label">
        <!-- Item dengan submenu -->
        <div v-if="item.children">
          <button
            @click="toggle(item.label)"
            class="sidebar-link w-full justify-between"
            :class="{ 'bg-white/10 text-white': isGroupActive(item) }"
            :aria-expanded="!!expanded[item.label]"
          >
            <span class="flex items-center gap-3">
              <span v-html="iconSvg(item.icon)" class="h-5 w-5 shrink-0"></span>
              {{ item.label }}
            </span>
            <svg class="h-4 w-4 transition-transform" :class="{ 'rotate-180': expanded[item.label] }" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M19.5 8.25l-7.5 7.5-7.5-7.5" /></svg>
          </button>
          <div v-show="expanded[item.label]" class="ml-4 mt-1 space-y-1 border-l border-white/10 pl-3">
            <RouterLink
              v-for="child in item.children" :key="child.label" :to="child.to"
              class="sidebar-link !py-2 text-sm"
              active-class="sidebar-link-active"
              @click="$emit('navigate')"
            >
              <span v-html="iconSvg(child.icon)" class="h-4 w-4 shrink-0"></span>
              {{ child.label }}
            </RouterLink>
          </div>
        </div>
        <!-- Item tunggal -->
        <RouterLink v-else :to="item.to" class="sidebar-link" active-class="sidebar-link-active" :exact="item.exact" @click="$emit('navigate')">
          <span v-html="iconSvg(item.icon)" class="h-5 w-5 shrink-0"></span>
          {{ item.label }}
        </RouterLink>
      </template>
    </template>
  </nav>
