import { reactive, watch } from 'vue';
import { useRoute } from 'vue-router';

const props = defineProps({ items: { type: Array, default: () => [] } });
defineEmits(['navigate']);
const route = useRoute();
const expanded = reactive({});

function isGroupActive(item) {
  return (item.children || []).some((c) => route.path === c.to || route.path.startsWith(c.to + '/'));
}
function toggle(label) {
  expanded[label] = !expanded[label];
}
// Buka otomatis grup yang memuat route aktif.
watch(() => route.path, () => {
  for (const group of props.items) {
    for (const item of group.items || []) {
      if (item.children && isGroupActive(item)) expanded[item.label] = true;
    }
  }
}, { immediate: true });

